import React from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid } from 'recharts';
import { useTranslation } from 'react-i18next';

export default function BarChartComponent({ data, date, provinces }) {
  const { t } = useTranslation();
  const chartData = provinces.map(prov => {
    const point = data.find(d => d.date === date && d.province === prov);
    return { province: prov, value: point ? point.value : 0 };
  });

  return (
    <div style={{ marginTop: 40 }}>
      <h2>{t('bar_chart_title', { date })}</h2>
      <BarChart width={700} height={300} data={chartData}>
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis dataKey="province" />
        <YAxis />
        <Tooltip />
        <Bar dataKey="value" />
      </BarChart>
    </div>
  );
}
